        ["The category was saved, but the list could not be reloaded. Click Refresh."] = ["Die Kategorie wurde gespeichert, aber die Liste konnte nicht neu geladen werden. Klicken Sie auf Aktualisieren.", "Категория сохранена, но список не удалось перезагрузить. Нажмите «Обновить».", "Категорію збережено, але список не вдалося перезавантажити. Натисніть «Оновити»."],
        ["Could not save the category. Click Refresh and try again."] = ["Kategorie konnte nicht gespeichert werden. Klicken Sie auf Aktualisieren und versuchen Sie es erneut.", "Не удалось сохранить категорию. Нажмите «Обновить» и повторите.", "Не вдалося зберегти категорію. Натисніть «Оновити» й повторіть."],
        ["Category deleted."] = ["Kategorie gelöscht.", "Категория удалена.", "Категорію видалено."],
        ["The category was already deleted. The list has been updated."] = ["Die Kategorie war schon gelöscht. Die Liste wurde aktualisiert.", "Категория уже удалена. Список обновлён.", "Категорію вже видалено. Список оновлено."],
        ["Could not delete the category. Try Refresh."] = ["Kategorie konnte nicht gelöscht werden. Versuchen Sie Aktualisieren.", "Не удалось удалить категорию. Нажмите «Обновить».", "Не вдалося видалити категорію. Натисніть «Оновити»."],
        ["Could not check where the category is used. Try Refresh."] = ["Verwendung der Kategorie konnte nicht geprüft werden. Versuchen Sie Aktualisieren.", "Не удалось проверить, где используется категория. Нажмите «Обновить».", "Не вдалося перевірити, де використовується категорія. Натисніть «Оновити»."],
        ["Could not move and delete the category. Nothing was changed. Try Refresh."] = ["Kategorie konnte nicht verschoben und gelöscht werden. Nichts wurde geändert. Versuchen Sie Aktualisieren.", "Не удалось перенести данные и удалить категорию. Ничего не изменено. Нажмите «Обновить».", "Не вдалося перенести дані й видалити категорію. Нічого не змінено. Натисніть «Оновити»."],
        ["Could not delete the category. Nothing was changed. Try Refresh."] = ["Kategorie konnte nicht gelöscht werden. Nichts wurde geändert. Versuchen Sie Aktualisieren.", "Не удалось удалить категорию. Ничего не изменено. Нажмите «Обновить».", "Не вдалося видалити категорію. Нічого не змінено. Натисніть «Оновити»."],
        ["Delete category?"] = ["Kategorie löschen?", "Удалить категорию?", "Видалити категорію?"],
        ["Delete category and all its data"] = ["Kategorie samt allen Daten löschen", "Удалить категорию со всеми данными", "Видалити категорію з усіма даними"],
        ["Delete everything?"] = ["Alles löschen?", "Удалить всё?", "Видалити все?"],
        ["Delete everything"] = ["Alles löschen", "Удалить всё", "Видалити все"],
        ["Move and delete?"] = ["Verschieben und löschen?", "Перенести и удалить?", "Перенести й видалити?"],
        ["Move and delete"] = ["Verschieben und löschen", "Перенести и удалить", "Перенести й видалити"],
        ["Move expenses and schedules to another category, or delete everything:"] = ["Ausgaben und Pläne in eine andere Kategorie verschieben oder alles löschen:", "Перенесите расходы и расписания в другую категорию или удалите всё:", "Перенесіть витрати й розклади до іншої категорії або видаліть усе:"],
        ["There is no other category to move them to. You can delete everything:"] = ["Es gibt keine andere Kategorie zum Verschieben. Sie können alles löschen:", "Другой категории для переноса нет. Можно удалить всё:", "Іншої категорії для перенесення немає. Можна видалити все:"],
        ["A backup is saved first, so you can undo this with Backup > Restore."] = ["Zuerst wird eine Sicherung gespeichert, so können Sie das mit Sicherung > Wiederherstellen rückgängig machen.", "Сначала сохраняется копия, поэтому это можно отменить через «Копия» > «Восстановить».", "Спершу зберігається копія, тож це можна скасувати через «Копія» > «Відновити»."],
        ["This cannot be undone."] = ["Das kann nicht rückgängig gemacht werden.", "Это нельзя отменить.", "Це неможливо скасувати."],
        ["Category operation failed."] = ["Kategorie-Vorgang fehlgeschlagen.", "Операция с категорией не удалась.", "Операція з категорією не вдалася."],

        // Budgets
        ["Set a limit for this month"] = ["Limit für diesen Monat setzen", "Задать лимит на этот месяц", "Задати ліміт на цей місяць"],
        ["A limit of 0 means no spending is budgeted for this category."] = ["Ein Limit von 0 bedeutet, dass für diese Kategorie nichts eingeplant ist.", "Лимит 0 означает, что на эту категорию траты не планируются.", "Ліміт 0 означає, що на цю категорію витрати не плануються."],
        ["No budgets set for this month."] = ["Für diesen Monat sind keine Budgets gesetzt.", "На этот месяц бюджетов нет.", "На цей місяць бюджетів немає."],
        ["Could not load budgets. Try Refresh."] = ["Budgets konnten nicht geladen werden. Versuchen Sie Aktualisieren.", "Не удалось загрузить бюджеты. Нажмите «Обновить».", "Не вдалося завантажити бюджети. Натисніть «Оновити»."],
        ["Enter an amount of 0 or more with up to 2 decimal places."] = ["Betrag ab 0 mit höchstens 2 Nachkommastellen eingeben.", "Введите сумму от 0 не более чем с 2 знаками после запятой.", "Введіть суму від 0 не більше ніж з 2 знаками після коми."],
        ["Budget saved."] = ["Budget gespeichert.", "Бюджет сохранён.", "Бюджет збережено."],
        ["The budget was saved, but the list could not be reloaded. Click Refresh."] = ["Das Budget wurde gespeichert, aber die Liste konnte nicht neu geladen werden. Klicken Sie auf Aktualisieren.", "Бюджет сохранён, но список не удалось перезагрузить. Нажмите «Обновить».", "Бюджет збережено, але список не вдалося перезавантажити. Натисніть «Оновити»."],
        ["Could not save the budget. Click Refresh and try again."] = ["Budget konnte nicht gespeichert werden. Klicken Sie auf Aktualisieren und versuchen Sie es erneut.", "Не удалось сохранить бюджет. Нажмите «Обновить» и повторите.", "Не вдалося зберегти бюджет. Натисніть «Оновити» й повторіть."],
        ["Budget limit removed."] = ["Budgetlimit entfernt.", "Лимит бюджета убран.", "Ліміт бюджету прибрано."],
        ["The limit was already removed. The list has been updated."] = ["Das Limit war schon entfernt. Die Liste wurde aktualisiert.", "Лимит уже убран. Список обновлён.", "Ліміт уже прибрано. Список оновлено."],
        ["Could not remove the budget limit. Try Refresh."] = ["Budgetlimit konnte nicht entfernt werden. Versuchen Sie Aktualisieren.", "Не удалось убрать лимит бюджета. Нажмите «Обновить».", "Не вдалося прибрати ліміт бюджету. Натисніть «Оновити»."],
        ["Budget operation failed."] = ["Budget-Vorgang fehlgeschlagen.", "Операция с бюджетом не удалась.", "Операція з бюджетом не вдалася."],
        ["Remove budget limit?"] = ["Budgetlimit entfernen?", "Убрать лимит бюджета?", "Прибрати ліміт бюджету?"],
        ["Remove the limit for this month? Your expenses will be kept."] = ["Limit für diesen Monat entfernen? Ihre Ausgaben bleiben erhalten.", "Убрать лимит на этот месяц? Расходы сохранятся.", "Прибрати ліміт на цей місяць? Витрати збережуться."],
        ["Spent: {0} / Limit: {1}"] = ["Ausgegeben: {0} / Limit: {1}", "Потрачено: {0} / Лимит: {1}", "Витрачено: {0} / Ліміт: {1}"],
        ["Over budget: {0}"] = ["Budget überschritten: {0}", "Превышение: {0}", "Перевищення: {0}"],
        ["Remaining: {0}"] = ["Übrig: {0}", "Осталось: {0}", "Залишилось: {0}"],

        // Recurring
        ["Edit schedule"] = ["Plan bearbeiten", "Изменить расписание", "Змінити розклад"],
        ["New schedule"] = ["Neuer Plan", "Новое расписание", "Новий розклад"],
        ["Create schedule"] = ["Plan erstellen", "Создать расписание", "Створити розклад"],
        ["No recurring expenses yet."] = ["Noch keine wiederkehrenden Ausgaben.", "Регулярных расходов пока нет.", "Регулярних витрат ще немає."],
        ["Creating a schedule also generates due expenses through today. Past start dates include missed occurrences."] = ["Beim Erstellen eines Plans werden auch fällige Ausgaben bis heute erzeugt. Bei einem Startdatum in der Vergangenheit sind verpasste Termine enthalten.", "При создании расписания также создаются расходы до сегодняшнего дня. Если дата начала в прошлом, включаются пропущенные разы.", "Під час створення розкладу також створюються витрати до сьогодні. Якщо дата початку в минулому, враховуються пропущені рази."],
        ["Changes apply to future expenses only. Expenses created earlier are not changed. A new frequency counts from the next due date."] = ["Änderungen gelten nur für künftige Ausgaben. Bereits erstellte Ausgaben bleiben unverändert. Eine neue Häufigkeit zählt ab dem nächsten Fälligkeitsdatum.", "Изменения касаются только будущих расходов. Уже созданные не меняются. Новая периодичность отсчитывается от следующей даты.", "Зміни стосуються лише майбутніх витрат. Уже створені не змінюються. Нова періодичність відраховується від наступної дати."],
        ["Could not load recurring expenses. Try Refresh."] = ["Wiederkehrende Ausgaben konnten nicht geladen werden. Versuchen Sie Aktualisieren.", "Не удалось загрузить регулярные расходы. Нажмите «Обновить».", "Не вдалося завантажити регулярні витрати. Натисніть «Оновити»."],
        ["Choose a start date."] = ["Startdatum wählen.", "Выберите дату начала.", "Оберіть дату початку."],
        ["Schedule created."] = ["Plan erstellt.", "Расписание создано.", "Розклад створено."],
        ["Schedule created. Due expenses added: {0}."] = ["Plan erstellt. Fällige Ausgaben hinzugefügt: {0}.", "Расписание создано. Добавлено расходов: {0}.", "Розклад створено. Додано витрат: {0}."],
        ["Could not create the schedule. Check the category and try again."] = ["Plan konnte nicht erstellt werden. Prüfen Sie die Kategorie und versuchen Sie es erneut.", "Не удалось создать расписание. Проверьте категорию и повторите.", "Не вдалося створити розклад. Перевірте категорію й повторіть."],
        ["The schedule was saved, but due expenses could not be generated. Click Generate due expenses to retry."] = ["Der Plan wurde gespeichert, aber fällige Ausgaben konnten nicht erzeugt werden. Klicken Sie auf «Fällige Ausgaben erzeugen».", "Расписание сохранено, но расходы создать не удалось. Нажмите «Создать просроченные расходы».", "Розклад збережено, але витрати створити не вдалося. Натисніть «Створити прострочені витрати»."],
        ["The schedule was saved and generation completed, but the list could not be reloaded. Try Refresh."] = ["Der Plan wurde gespeichert und die Erzeugung abgeschlossen, aber die Liste konnte nicht neu geladen werden. Versuchen Sie Aktualisieren.", "Расписание сохранено, расходы созданы, но список не удалось перезагрузить. Нажмите «Обновить».", "Розклад збережено, витрати створено, але список не вдалося перезавантажити. Натисніть «Оновити»."],
        ["Schedule updated. Expenses created earlier were not changed."] = ["Plan aktualisiert. Früher erstellte Ausgaben wurden nicht geändert.", "Расписание обновлено. Ранее созданные расходы не менялись.", "Розклад оновлено. Раніше створені витрати не змінювались."],
        ["The schedule was updated, but the list could not be reloaded. Try Refresh."] = ["Der Plan wurde aktualisiert, aber die Liste konnte nicht neu geladen werden. Versuchen Sie Aktualisieren.", "Расписание обновлено, но список не удалось перезагрузить. Нажмите «Обновить».", "Розклад оновлено, але список не вдалося перезавантажити. Натисніть «Оновити»."],
        ["Could not update the schedule. Check the values and try again."] = ["Plan konnte nicht aktualisiert werden. Prüfen Sie die Werte und versuchen Sie es erneut.", "Не удалось обновить расписание. Проверьте значения и повторите.", "Не вдалося оновити розклад. Перевірте значення й повторіть."],
        ["Enter a positive amount with up to 2 decimal places."] = ["Positiven Betrag mit höchstens 2 Nachkommastellen eingeben.", "Введите положительную сумму не более чем с 2 знаками после запятой.", "Введіть додатну суму не більше ніж з 2 знаками після коми."],
        ["Choose a frequency."] = ["Häufigkeit wählen.", "Выберите периодичность.", "Оберіть періодичність."],
        ["Choose an end date."] = ["Enddatum wählen.", "Выберите дату окончания.", "Оберіть дату завершення."],
        ["End date cannot be before the start date."] = ["Das Enddatum darf nicht vor dem Startdatum liegen.", "Дата окончания не может быть раньше даты начала.", "Дата завершення не може бути раніше за дату початку."],
        ["Due expenses added: {0}."] = ["Fällige Ausgaben hinzugefügt: {0}.", "Добавлено расходов: {0}.", "Додано витрат: {0}."],
        ["Generation completed, but the list could not be reloaded. Try Refresh."] = ["Erzeugung abgeschlossen, aber die Liste konnte nicht neu geladen werden. Versuchen Sie Aktualisieren.", "Создание завершено, но список не удалось перезагрузить. Нажмите «Обновить».", "Створення завершено, але список не вдалося перезавантажити. Натисніть «Оновити»."],
        ["Could not generate due expenses. Try again."] = ["Fällige Ausgaben konnten nicht erzeugt werden. Versuchen Sie es erneut.", "Не удалось создать расходы. Повторите попытку.", "Не вдалося створити витрати. Повторіть спробу."],
        ["Schedule deactivated."] = ["Plan deaktiviert.", "Расписание отключено.", "Розклад вимкнено."],
        ["Could not deactivate the schedule. Try Refresh."] = ["Plan konnte nicht deaktiviert werden. Versuchen Sie Aktualisieren.", "Не удалось отключить расписание. Нажмите «Обновить».", "Не вдалося вимкнути розклад. Натисніть «Оновити»."],
        ["Schedule reactivated."] = ["Plan reaktiviert.", "Расписание включено снова.", "Розклад увімкнено знову."],
        ["Could not reactivate the schedule. Try Refresh."] = ["Plan konnte nicht reaktiviert werden. Versuchen Sie Aktualisieren.", "Не удалось включить расписание. Нажмите «Обновить».", "Не вдалося увімкнути розклад. Натисніть «Оновити»."],
        ["Schedule deleted. Its expenses were kept."] = ["Plan gelöscht. Seine Ausgaben bleiben erhalten.", "Расписание удалено. Его расходы сохранены.", "Розклад видалено. Його витрати збережено."],
        ["Could not delete the schedule. Try Refresh."] = ["Plan konnte nicht gelöscht werden. Versuchen Sie Aktualisieren.", "Не удалось удалить расписание. Нажмите «Обновить».", "Не вдалося видалити розклад. Натисніть «Оновити»."],
        ["Recurring expense operation failed."] = ["Vorgang für wiederkehrende Ausgabe fehlgeschlagen.", "Операция с регулярным расходом не удалась.", "Операція з регулярною витратою не вдалася."],
        ["Delete schedule?"] = ["Plan löschen?", "Удалить расписание?", "Видалити розклад?"],
        ["Delete this schedule? Expenses it already created will be kept."] = ["Diesen Plan löschen? Bereits erstellte Ausgaben bleiben erhalten.", "Удалить это расписание? Уже созданные расходы сохранятся.", "Видалити цей розклад? Уже створені витрати збережуться."],
        ["Deactivate schedule?"] = ["Plan deaktivieren?", "Отключить расписание?", "Вимкнути розклад?"],
        ["Stop generating expenses for this schedule? Existing expenses will be kept."] = ["Erzeugung von Ausgaben für diesen Plan stoppen? Vorhandene Ausgaben bleiben erhalten.", "Прекратить создание расходов по этому расписанию? Существующие расходы сохранятся.", "Припинити створення витрат за цим розкладом? Наявні витрати збережуться."],
        ["Start: {0:dd.MM.yyyy}"] = ["Start: {0:dd.MM.yyyy}", "Начало: {0:dd.MM.yyyy}", "Початок: {0:dd.MM.yyyy}"],
        ["Ends: {0:dd.MM.yyyy}"] = ["Endet: {0:dd.MM.yyyy}", "Окончание: {0:dd.MM.yyyy}", "Завершення: {0:dd.MM.yyyy}"],
        ["Next due: {0:dd.MM.yyyy}"] = ["Nächste Fälligkeit: {0:dd.MM.yyyy}", "Следующая дата: {0:dd.MM.yyyy}", "Наступна дата: {0:dd.MM.yyyy}"],
        ["Inactive"] = ["Inaktiv", "Отключено", "Вимкнено"],

        // Reports
        ["Could not build the report. Try again."] = ["Bericht konnte nicht erstellt werden. Versuchen Sie es erneut.", "Не удалось построить отчёт. Повторите попытку.", "Не вдалося побудувати звіт. Повторіть спробу."],
        ["Total: {0:N2} {1}"] = ["Gesamt: {0:N2} {1}", "Итого: {0:N2} {1}", "Разом: {0:N2} {1}"],
        ["Previous month: {0:N2} {1}"] = ["Vormonat: {0:N2} {1}", "Прошлый месяц: {0:N2} {1}", "Минулий місяць: {0:N2} {1}"],
        ["Average per day: no days have passed yet"] = ["Durchschnitt pro Tag: noch keine Tage vergangen", "В среднем за день: дни ещё не прошли", "У середньому за день: днів ще не минуло"],
        ["Average per day: {0:N2} {1} (over {2} days)"] = ["Durchschnitt pro Tag: {0:N2} {1} (über {2} Tage)", "В среднем за день: {0:N2} {1} (за {2} дн.)", "У середньому за день: {0:N2} {1} (за {2} дн.)"],
        ["Forecast for the whole month: {0:N2} {1}"] = ["Prognose für den ganzen Monat: {0:N2} {1}", "Прогноз на весь месяц: {0:N2} {1}", "Прогноз на весь місяць: {0:N2} {1}"],

        // Rules
        ["No rules yet. Add your first rule above."] = ["Noch keine Regeln. Fügen Sie oben Ihre erste Regel hinzu.", "Правил пока нет. Добавьте первое выше.", "Правил ще немає. Додайте перше вище."],
        ["When the description of a bank record contains the text, the CSV import preview puts it into the chosen category. Upper and lower case do not matter. If several rules fit, the longest text wins."] = ["Enthält die Beschreibung eines Bankeintrags den Text, ordnet die CSV-Importvorschau ihn der gewählten Kategorie zu. Groß- und Kleinschreibung spielt keine Rolle. Passen mehrere Regeln, gewinnt der längste Text.", "Если описание банковской записи содержит этот текст, предпросмотр импорта CSV отнесёт её к выбранной категории. Регистр не важен. Если подходит несколько правил, побеждает самый длинный текст.", "Якщо опис банківського запису містить цей текст, попередній перегляд імпорту CSV віднесе його до обраної категорії. Регістр не важливий. Якщо підходить кілька правил, перемагає найдовший текст."],
        ["Could not load the rules. Try Refresh."] = ["Regeln konnten nicht geladen werden. Versuchen Sie Aktualisieren.", "Не удалось загрузить правила. Нажмите «Обновить».", "Не вдалося завантажити правила. Натисніть «Оновити»."],
        ["Enter the text to look for."] = ["Suchtext eingeben.", "Введите текст для поиска.", "Введіть текст для пошуку."],
        ["A rule with this text already exists."] = ["Eine Regel mit diesem Text existiert bereits.", "Правило с таким текстом уже есть.", "Правило з таким текстом уже є."],
        ["Rule added."] = ["Regel hinzugefügt.", "Правило добавлено.", "Правило додано."],
        ["The rule was added, but the list could not be reloaded. Click Refresh."] = ["Die Regel wurde hinzugefügt, aber die Liste konnte nicht neu geladen werden. Klicken Sie auf Aktualisieren.", "Правило добавлено, но список не удалось перезагрузить. Нажмите «Обновить».", "Правило додано, але список не вдалося перезавантажити. Натисніть «Оновити»."],
        ["Could not add the rule. Try again."] = ["Regel konnte nicht hinzugefügt werden. Versuchen Sie es erneut.", "Не удалось добавить правило. Повторите попытку.", "Не вдалося додати правило. Повторіть спробу."],
        ["Rule deleted."] = ["Regel gelöscht.", "Правило удалено.", "Правило видалено."],
        ["Could not delete the rule. Try Refresh."] = ["Regel konnte nicht gelöscht werden. Versuchen Sie Aktualisieren.", "Не удалось удалить правило. Нажмите «Обновить».", "Не вдалося видалити правило. Натисніть «Оновити»."],
        ["Delete rule?"] = ["Regel löschen?", "Удалить правило?", "Видалити правило?"],

        // Import
        ["Choose a file, tick the records to import and set a category for each one (the default category is used until you change it), then press Import selected. Records already imported are skipped."] = ["Wählen Sie eine Datei, haken Sie die zu importierenden Einträge an und setzen Sie je eine Kategorie (bis zur Änderung gilt die Standardkategorie), dann drücken Sie «Auswahl importieren». Bereits importierte Einträge werden übersprungen.", "Выберите файл, отметьте записи для импорта и задайте категорию для каждой (пока не измените — используется категория по умолчанию), затем нажмите «Импортировать выбранные». Уже импортированные записи пропускаются.", "Оберіть файл, позначте записи для імпорту й задайте категорію для кожної (поки не змінено — використовується категорія за замовчуванням), потім натисніть «Імпортувати вибрані». Уже імпортовані записи пропускаються."],
        ["How is this file written?"] = ["Wie ist diese Datei aufgebaut?", "Как записан этот файл?", "Як записано цей файл?"],
        ["The statement contains no transactions."] = ["Der Kontoauszug enthält keine Buchungen.", "В выписке нет операций.", "У виписці немає операцій."],
        ["Date format examples: yyyy-MM-dd, dd.MM.yyyy, MM/dd/yyyy (MM is the month, mm is minutes)."] = ["Beispiele für Datumsformate: yyyy-MM-dd, dd.MM.yyyy, MM/dd/yyyy (MM ist der Monat, mm sind Minuten).", "Примеры формата даты: yyyy-MM-dd, dd.MM.yyyy, MM/dd/yyyy (MM — месяц, mm — минуты).", "Приклади формату дати: yyyy-MM-dd, dd.MM.yyyy, MM/dd/yyyy (MM — місяць, mm — хвилини)."],
        ["Revolut (German column names)"] = ["Revolut (deutsche Spaltennamen)", "Revolut (немецкие названия столбцов)", "Revolut (німецькі назви стовпців)"],
        ["Other bank CSV (choose the columns)"] = ["CSV einer anderen Bank (Spalten wählen)", "CSV другого банка (выбрать столбцы)", "CSV іншого банку (обрати стовпці)"],
        ["Choose a CSV file, tell the app how it is written, then press Show preview."] = ["Wählen Sie eine CSV-Datei, geben Sie an, wie sie aufgebaut ist, und drücken Sie «Vorschau anzeigen».", "Выберите файл CSV, укажите, как он записан, и нажмите «Показать предпросмотр».", "Оберіть файл CSV, вкажіть, як його записано, і натисніть «Показати попередній перегляд»."],
        ["Revolut CSV with German column names · {0}"] = ["Revolut-CSV mit deutschen Spaltennamen · {0}", "Revolut CSV с немецкими названиями столбцов · {0}", "Revolut CSV з німецькими назвами стовпців · {0}"],
