        ["Needs review: {0} · Ignored: {1}"] = ["Zu prüfen: {0} · Ignoriert: {1}", "Нужна проверка: {0} · Игнорируется: {1}", "Потрібна перевірка: {0} · Ігнорується: {1}"],
