        [" (+{0} deleted, kept in history)"] = [" (+{0} gelöscht, im Verlauf behalten)", " (+{0} удалено, хранится в истории)", " (+{0} видалено, зберігається в історії)"],
        ["\"{0}\" is used by {1} expenses{2}, {3} schedules and {4} budget limits. "] = ["\"{0}\" wird von {1} Ausgaben{2}, {3} Plänen und {4} Budgetlimits verwendet. ", "«{0}» используется в расходах ({1}){2}, расписаниях ({3}) и лимитах бюджета ({4}). ", "«{0}» використовується у витратах ({1}){2}, розкладах ({3}) і лімітах бюджету ({4}). "],
