        ["Move the data of \"{0}\" to \"{1}\" and delete \"{0}\"?"] = ["Daten von \"{0}\" nach \"{1}\" verschieben und \"{0}\" löschen?", "Перенести данные «{0}» в «{1}» и удалить «{0}»?", "Перенести дані «{0}» до «{1}» і видалити «{0}»?"],
        ["Its {0} budget limits will be removed."] = ["Seine {0} Budgetlimits werden entfernt.", "Его лимиты бюджета ({0}) будут убраны.", "Його ліміти бюджету ({0}) буде прибрано."],

